import{_ as a,o as t,c as o,ah as i}from"./chunks/framework.DDXs_i7t.js";const m=JSON.parse('{"title":"The Lawsuit Machine: Michael Rami and the Jurisprudence of Intimidation","description":"From Constitutional Judge to Media Executioner: How Michael Rami uses the law to silence critics of power.","frontmatter":{"title":"The Lawsuit Machine: Michael Rami and the Jurisprudence of Intimidation","description":"From Constitutional Judge to Media Executioner: How Michael Rami uses the law to silence critics of power.","date":"2026-04-07T00:00:00.000Z"},"headers":[],"relativePath":"en/logbuch/2026-04-07-michael-rami-lawsuit-machine.md","filePath":"en/logbuch/2026-04-07-michael-rami-lawsuit-machine.md"}'),n={name:"en/logbuch/2026-04-07-michael-rami-lawsuit-machine.md"};function s(r,e,h,l,c,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="the-lawsuit-machine-michael-rami-and-the-jurisprudence-of-intimidation" tabindex="-1">The Lawsuit Machine: Michael Rami and the Jurisprudence of Intimidation <a class="header-anchor" href="#the-lawsuit-machine-michael-rami-and-the-jurisprudence-of-intimidation" aria-label="Permalink to &quot;The Lawsuit Machine: Michael Rami and the Jurisprudence of Intimidation&quot;">​</a></h1><p><strong>Vienna, April 7, 2026</strong> – While our project&#39;s virality index breaks the 500,000 mark, we take a look at an actor who secures the architecture of power in the background with legal severity: <strong>Michael Rami</strong>.</p><p>In the world of the &quot;Horten Mystery&quot;, there is not only money and politics, there are also the &quot;cleaners&quot; who ensure that uncomfortable questions become expensive. Very expensive.</p><h2 id="the-constitutional-judge-as-a-cease-and-desist-pro" tabindex="-1">The Constitutional Judge as a Cease-and-Desist Pro <a class="header-anchor" href="#the-constitutional-judge-as-a-cease-and-desist-pro" aria-label="Permalink to &quot;The Constitutional Judge as a Cease-and-Desist Pro&quot;">​</a></h2><p>Michael Rami is a phenomenon of the Austrian special class. He sits as a judge nominated by the FPÖ at the <strong>Constitutional Court (VfGH)</strong> – the holy grail of the rule of law. But when he takes off the robe, he swings the legal axe for the political elite.</p><p>Particularly remembered: The wave of lawsuits on behalf of <strong>Katharina Nehammer</strong>, the wife of the Federal Chancellor.</p><ul><li><strong>The Business Model:</strong> Hundreds of private individuals who had shared a (admittedly false) post about mask deals on Facebook received mail from Rami.</li><li><strong>The Price:</strong> Around 4,500 euros per person. One click, one shared post – and your existence is at stake.</li><li><strong>The Message:</strong> Don&#39;t mess with the Chancellor&#39;s family. Criticism or even just spreading rumors becomes a financial neck-breaker.</li></ul><h2 id="cobra-gate-and-the-wall-of-silence" tabindex="-1">Cobra-Gate and the Wall of Silence <a class="header-anchor" href="#cobra-gate-and-the-wall-of-silence" aria-label="Permalink to &quot;Cobra-Gate and the Wall of Silence&quot;">​</a></h2><p>Rami is the man for the rough work when it comes to freezing rumors. Whether it&#39;s the intoxicated Cobra officers in the Nehammer household or the entanglements around <em>Hygiene Austria</em> – Rami&#39;s strategy is always the same: <strong>legal escalation.</strong></p><p>Instead of shining through transparency, the system relies on intimidation. Anyone who dares to call the &quot;Schweinereien&quot; (dirty tricks) by name finds themselves in court, faced with a man who watches over the constitution during the day.</p><h2 id="the-analogy-shop-windows-and-paragraphs" tabindex="-1">The Analogy: Shop Windows and Paragraphs <a class="header-anchor" href="#the-analogy-shop-windows-and-paragraphs" aria-label="Permalink to &quot;The Analogy: Shop Windows and Paragraphs&quot;">​</a></h2><p>Helmut Horten controlled the shop windows of the consumer world. Michael Rami controls the shop windows of public opinion through paragraphs. In our project, he symbolizes the <strong>&quot;Pointillism of Paragraphs&quot;</strong>: each lawsuit is a small dot that eventually creates a picture of fear.</p><p>We are integrating this type of &quot;system lawyer&quot; into <strong>Part 4 of our screenplay</strong>. He is the one who does not burn the files, but locks them behind a wall of lawsuit threats.</p><p><em>The index continues to rise. Justice grinds. We document.</em></p><hr><p>👈 <a href="/en/logbuch/">Back to Logbook</a> 🔮 <a href="/en/orakel.html">Consult the Oracle for Justice</a></p>',16)])])}const p=a(n,[["render",s]]);export{m as __pageData,p as default};
